CREATE TABLE "receipt_templates" (
 "id" TEXT PRIMARY KEY, "scope" TEXT NOT NULL, "kind" TEXT NOT NULL CHECK ("kind" IN ('CUSTOMER','PRODUCTION','PACKING','SETTLEMENT')),
 "outletId" TEXT REFERENCES "outlets"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
 "settings" JSONB NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1 CHECK ("revision">0),
 "updatedById" TEXT REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
 "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT receipt_template_scope_check CHECK ("scope"=COALESCE("outletId",'GLOBAL')));
CREATE UNIQUE INDEX "receipt_templates_scope_kind_key" ON "receipt_templates"("scope","kind");
